const App: React.FC = () => {
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [articles, setArticles] = useState<Article[]>([]);
  const [loading, setLoading] = useState(false);
  const [selectedArticle, setSelectedArticle] = useState<Article | null>(null);
  const [timeRange, setTimeRange] = useState(1); // 1 month default

  // Load profile from local storage on mount
  useEffect(() => {
    const saved = localStorage.getItem('dmd_user_profile');
    if (saved) {
      setProfile(JSON.parse(saved));
    }
  }, []);

  // Fetch articles when profile or time range changes
  useEffect(() => {
    if (profile?.isConfigured) {
      const fetchFeed = async () => {
        setLoading(true);
        try {
          // Pass interests to help sorting later (API filtering is basic)
          const data = await searchArticles(timeRange, profile.interests);
          setArticles(data);
        } catch (e) {
          console.error(e);
        } finally {
          setLoading(false);
        }
      };
      fetchFeed();
    }
  }, [profile, timeRange]);

  const handleProfileComplete = (newProfile: UserProfile) => {
    localStorage.setItem('dmd_user_profile', JSON.stringify(newProfile));
    setProfile(newProfile);
  };

  const handleLogout = () => {
    localStorage.removeItem('dmd_user_profile');
    setProfile(null);
    setArticles([]);
  };

  if (!profile) {
    return <Onboarding onComplete={handleProfileComplete} />;
  }

  return (
    <div className="min-h-screen bg-slate-50 font-sans text-gray-900">

      {/* Header */}
      <header className="bg-white sticky top-0 z-30 border-b border-gray-200 shadow-sm">
