          <div className="flex items-center gap-2">
            <div className="bg-brand-600 p-2 rounded-lg">
                <Dna className="w-5 h-5 text-white" />
            </div>
            <span className="font-bold text-xl tracking-tight text-gray-800">DMD Companion</span>
          </div>

          <div className="flex items-center gap-4">
             <div className="hidden md:flex items-center text-xs text-gray-500 bg-gray-100 px-3 py-1 rounded-full">
                <span className="font-medium text-gray-700 mr-1">Profile:</span> {profile.ageGroup}, {profile.ambulatoryStatus}
             </div>
             <button 
                onClick={handleLogout}
                className="text-gray-400 hover:text-gray-600 transition-colors"
                title="Reset Profile"
             >
                <LogOut className="w-5 h-5" />
             </button>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">

        {/* Intro Banner */}
        <div className="bg-gradient-to-r from-brand-600 to-brand-800 rounded-2xl p-6 md:p-10 text-white mb-10 shadow-lg relative overflow-hidden">
            <div className="absolute top-0 right-0 opacity-10 transform translate-x-10 -translate-y-10">
                <Sparkles className="w-64 h-64" />
            </div>
            <div className="relative z-10 max-w-2xl">
                <h1 className="text-3xl font-bold mb-3">Latest Research for You</h1>
                <p className="text-brand-100 text-lg leading-relaxed mb-6">
                    Every week we scan medical journals for new DMD research. We summarize them in plain language and let you ask specific questions about how they affect your family.
                </p>
                <div className="flex gap-3">
                    <button onClick={() => setTimeRange(1)} className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${timeRange === 1 ? 'bg-white text-brand-700' : 'bg-brand-700/50 text-white hover:bg-brand-700'}`}>Last Month</button>
