import { ClinicalTrial } from '../types';

const BASE_URL = 'https://clinicaltrials.gov/api/v2/studies';

export const fetchDmdTrials = async (): Promise<ClinicalTrial[]> => {
  try {
    const query = encodeURIComponent('Duchenne Muscular Dystrophy');
    // We filter for active/recruiting trials
    const statusFilter = 'RECRUITING|ENROLLING_BY_INVITATION|ACTIVE_NOT_RECRUITING';
    const url = `${BASE_URL}?query.cond=${query}&filter.overallStatus=${statusFilter}&pageSize=20`;

    const response = await fetch(url);
    if (!response.ok) throw new Error('Failed to fetch trials');
    const data = await response.json();

    return data.studies.map((s: any) => {
      const protocol = s.protocolSection;
      return {
        nctId: protocol.identificationModule.nctId,
        title: protocol.identificationModule.officialTitle || protocol.identificationModule.briefTitle,
        status: protocol.statusModule.overallStatus,
        phase: protocol.designModule?.phases || [],
        conditions: protocol.conditionsModule?.conditions || [],
        locations: protocol.contactsLocationsModule?.locations?.map((l: any) => l.facility) || [],
        summary: protocol.descriptionModule?.briefSummary || "",
        eligibility: protocol.eligibilityModule?.eligibilityCriteria || "",
        lastUpdate: protocol.statusModule.lastUpdatePostDateStruct?.date || ""
      };
    });
  } catch (error) {
    console.error("ClinicalTrials Error:", error);
    return [];
  }
};

import { FDADrug } from '../types';

const BASE_URL = 'https://api.fda.gov/drug/label.json';

export const fetchDmdDrugs = async (): Promise<FDADrug[]> => {
  try {
    const query = encodeURIComponent('indications_and_usage:"Duchenne muscular dystrophy"');
    const url = `${BASE_URL}?search=${query}&limit=20`;

    const response = await fetch(url);
    if (!response.ok) throw new Error('Failed to fetch FDA drugs');
    const data = await response.json();

    // Map and deduplicate by brand name
    const seen = new Set();
    const results: FDADrug[] = [];

    for (const res of data.results) {
      const brandName = res.openfda?.brand_name?.[0] || "Unknown Therapy";
      if (seen.has(brandName)) continue;
      seen.add(brandName);

      results.push({
        brandName,
        genericName: res.openfda?.generic_name?.[0] || "",
        manufacturer: res.openfda?.manufacturer_name?.[0] || "",
        approvalDate: res.effective_time ? `${res.effective_time.substring(0,4)}-${res.effective_time.substring(4,6)}` : "Recent",
        indication: res.indications_and_usage?.[0]?.substring(0, 300) + "..." || "",
        labelUrl: `https://www.accessdata.fda.gov/scripts/cder/daf/index.cfm?event=BasicSearch.process&searchTerm=${brandName}`
      });
    }
    return results;
  } catch (error) {
    console.error("FDA API Error:", error);
    // Fallback list of key DMD drugs if API fails or is sparse
    return [
      { brandName: "Elevidys", genericName: "delandistrogene moxeparvovec-rokl", manufacturer: "Sarepta Therapeutics", approvalDate: "2023-06", indication: "Gene therapy for ambulatory pediatric patients...", labelUrl: "https://www.fda.gov" },
      { brandName: "Agamree", genericName: "vamorolone", manufacturer: "Santhera", approvalDate: "2023-10", indication: "Corticosteroid alternative...", labelUrl: "https://www.fda.gov" },
      { brandName: "Duvyzat", genericName: "givinostat", manufacturer: "Italfarmaco", approvalDate: "2024-03", indication: "HDAC inhibitor for patients 6 years and older...", labelUrl: "https://www.fda.gov" }
    ];
  }
};

