export const analyzeTrial = async (trial: ClinicalTrial, profile: UserProfile): Promise<string> => {
    const ai = getClient();
    const prompt = `
    作为DMD临床试验顾问，请分析以下试验与患者的匹配度。

    患者信息：
    - 年龄: ${profile.ageGroup}
    - 基因: ${profile.geneticProfile}
    - 状态: ${profile.ambulatoryStatus}
    - 地区: ${profile.region}

    试验信息：
    - 标题: ${trial.title}
    - 阶段: ${trial.phase.join(', ')}
    - 状态: ${trial.status}
    - 入排标准: ${trial.eligibility}

    任务:
    1. **匹配度评估**: 给出一个大致的匹配百分比，并解释原因。
    2. **关键准入条件**: 列出对该患者最重要的3-4条入组要求。
    3. **潜在风险与收益**: 简述该试验的风险。
    4. **下一步行动**: 给家属的建议。

    请加粗小标题，并使用通俗易懂的中文。`;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: prompt,
        });
        return response.text || "无法完成试验匹配分析。";
    } catch (error) {
        return "AI分析服务暂时中断。";
    }
};

export const chatWithArticle = async (
    history: ChatMessage[], 
    newMessage: string, 
    context: string,
    profile: UserProfile
): Promise<string> => {
    const ai = getClient();
    const systemInstruction = `
    你是DMD研究的AI解读员。你正在与一位家庭成员交谈。
    请始终保持友善，使用通俗易懂的中文，并基于提供的上下文回答。

    上下文背景:
    ${context}

    患者背景:
    ${profile.ambulatoryStatus}, ${profile.ageGroup}。

    规则:
    - 如果给出建议，必须包含免责声明: "${DISCLAIMER}"
    `;

    try {
        const chat = ai.chats.create({
            model: 'gemini-3-flash-preview',
            config: { systemInstruction },
            history: history.map(h => ({ role: h.role, parts: [{ text: h.text }] }))
        });
        const result = await chat.sendMessage({ message: newMessage });
        return result.text;
    } catch (error) {
        return "回复失败。";
    }
};

