import React, { useState, useEffect, useRef } from 'react';
import { FDADrug, UserProfile, ChatMessage, SavedInquiry } from '../types';
import { analyzeDrug, chatWithArticle } from '../services/geminiService';
import { saveInquiry } from '../services/authService';
import { X, Send, Bot, User, ShieldCheck, AlertTriangle, Save, Check, Pill, Factory, Clock, Microscope, Loader2 } from 'lucide-react';
import ReactMarkdown from 'react-markdown';

interface Props {
  drug: FDADrug;
  profile: UserProfile;
  onClose: () => void;
}

export const DrugInterpreterModal: React.FC<Props> = ({ drug, profile, onClose }) => {
  const [analysis, setAnalysis] = useState<string>('');
  const [loading, setLoading] = useState(true);
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [chatLoading, setChatLoading] = useState(false);
  const [saved, setSaved] = useState(false);
  const [saving, setSaving] = useState(false);

  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    let isMounted = true;
    const init = async () => {
      setLoading(true);
      const result = await analyzeDrug(drug, profile);
      if (isMounted) {
        setAnalysis(result);
        setLoading(false);
      }
    };
    init();
    return () => { isMounted = false; };
  }, [drug, profile]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [chatHistory, analysis]);

  const handleSend = async () => {
    if (!input.trim() || chatLoading) return;

    const userMsg: ChatMessage = { role: 'user', text: input };
    setChatHistory(prev => [...prev, userMsg]);
    setInput('');
    setChatLoading(true);

    const context = `药物: ${drug.brandName} (${drug.brandNameCn})\n适应症: ${drug.indication}\n剂量: ${drug.dosage}\n分析内容: ${analysis}`;
    const responseText = await chatWithArticle(chatHistory, userMsg.text, context, profile);

    const botMsg: ChatMessage = { role: 'model', text: responseText };
    setChatHistory(prev => [...prev, botMsg]);
    setChatLoading(false);
  };

  const handleSave = async () => {
      setSaving(true);
      const inquiry: SavedInquiry = {
          id: `drug-${drug.brandName}-${Date.now()}`,
          date: new Date().toLocaleDateString('zh-CN'),
          articleId: drug.brandName,
          articleTitle: `药物适配: ${drug.brandNameCn || drug.brandName}`,
          summary: analysis,
          chatHistory: chatHistory
      };
      await saveInquiry(inquiry);
      setSaving(false);
      setSaved(true);
      setTimeout(() => setSaved(false), 3000);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-gray-900/70 backdrop-blur-sm">
      <div className="bg-white w-full max-w-6xl h-[90vh] rounded-2xl flex flex-col shadow-2xl overflow-hidden animate-in fade-in zoom-in-95 duration-200">

        {/* Header */}
        <div className="p-4 border-b border-gray-100 flex items-center justify-between bg-white shrink-0">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-brand-100 rounded-xl shrink-0">
                <Pill className="w-5 h-5 text-brand-600" />
            </div>
            <h2 className="font-bold text-gray-900 text-lg">药物病情适配解读</h2>
          </div>
          <div className="flex items-center gap-2 shrink-0">
            <button 
                onClick={handleSave}
                disabled={loading || saved || saving}
                className={`flex items-center px-4 py-2 rounded-lg text-sm font-medium transition-all ${
                    saved 
                    ? 'bg-green-100 text-green-700' 
                    : 'bg-brand-50 text-brand-700 hover:bg-brand-100'
                }`}
            >
                {saving ? <Loader2 className="w-4 h-4 mr-1 animate-spin"/> : saved ? <Check className="w-4 h-4 mr-1"/> : <Save className="w-4 h-4 mr-1"/>}
                {saved ? '已保存' : saving ? '保存中...' : '保存咨询'}
            </button>
            <button onClick={onClose} className="p-2 hover:bg-gray-100 rounded-full transition-colors">
                <X className="w-6 h-6 text-gray-500" />
            </button>
          </div>
        </div>

        {/* Content Area */}
        <div className="flex-1 flex flex-col md:flex-row overflow-hidden">

            {/* Left Panel: Drug Details & AI Analysis */}
            <div className="w-full md:w-1/2 overflow-y-auto p-6 border-r border-gray-100 bg-gray-50/50">

                {/* Drug Basic Info Card */}
                <div className="bg-white p-5 rounded-xl border border-gray-200 shadow-sm mb-6">
                    <div className="flex items-center justify-between mb-4">
                        <h3 className="text-xl font-black text-gray-900">
                            {drug.brandNameCn || drug.brandName}
                            <span className="block text-sm font-medium text-gray-400 font-sans tracking-tight">{drug.brandName} / {drug.genericName}</span>
                        </h3>
                        <div className="bg-brand-600 text-white px-3 py-1 rounded-lg text-xs font-bold shadow-sm">
                            FDA Approved {drug.approvalYear}
                        </div>
                    </div>

                    <div className="grid grid-cols-2 gap-4 mb-4">
                        <div className="flex items-center gap-2 text-sm text-gray-600">
                            <Factory className="w-4 h-4 text-brand-500 shrink-0" />
                            <span className="truncate">{drug.manufacturer}</span>
                        </div>
                        <div className="flex items-center gap-2 text-sm text-gray-600">
                            <Clock className="w-4 h-4 text-brand-500 shrink-0" />
                            <span>获批日期: {drug.approvalDate}</span>
                        </div>
                    </div>

                    <div className="space-y-3 pt-3 border-t border-gray-100">
                        <div className="flex items-start gap-2 text-sm">
                            <Microscope className="w-4 h-4 text-brand-600 shrink-0 mt-0.5" />
                            <p className="text-gray-700"><span className="font-bold text-gray-900">适应症：</span>{drug.indication}</p>
                        </div>
                        <div className="flex items-start gap-2 text-sm">
                            <ShieldCheck className="w-4 h-4 text-brand-600 shrink-0 mt-0.5" />
                            <p className="text-gray-700"><span className="font-bold text-gray-900">剂量信息：</span>{drug.dosage}</p>
                        </div>
                    </div>
                </div>

                <div className="relative">
                    <h3 className="text-sm font-bold text-gray-500 uppercase tracking-wider mb-4 flex items-center">
                        <span className="w-2 h-2 rounded-full bg-brand-500 mr-2"></span>
                        AI 智能适配解读
                    </h3>

                    {loading ? (
                        <div className="space-y-4 animate-pulse">
                            <div className="h-4 bg-gray-200 rounded w-3/4"></div>
                            <div className="h-4 bg-gray-200 rounded w-full"></div>
                            <div className="h-4 bg-gray-200 rounded w-5/6"></div>
                            <div className="h-32 bg-gray-200 rounded w-full mt-6"></div>
                            <p className="text-center text-gray-400 text-sm mt-4">AI 正在对比患者病情与药物适应症...</p>
                        </div>
                    ) : (
                        <div className="prose prose-sm prose-brand max-w-none text-gray-700 leading-relaxed bg-white p-5 rounded-xl border border-gray-100">
                            <ReactMarkdown>{analysis}</ReactMarkdown>
                        </div>
                    )}

                    {!loading && (
                        <div className="mt-8 p-4 bg-amber-50 border border-amber-200 rounded-xl flex gap-3 items-start">
                            <AlertTriangle className="w-5 h-5 text-amber-500 shrink-0 mt-0.5" />
                            <p className="text-xs text-amber-800 leading-5">
                                提醒：此适配分析由 AI 生成。具体用药、剂量调整及副作用管理，必须遵循您的主治医生建议。
                            </p>
                        </div>
                    )}
                </div>
            </div>

            {/* Right Panel: Chat */}
            <div className="flex-1 flex flex-col bg-white border-t md:border-t-0">
                <div className="flex-1 overflow-y-auto p-4 space-y-4" ref={scrollRef}>
                    <div className="flex gap-3">
                        <div className="w-9 h-9 rounded-full bg-brand-100 flex items-center justify-center shrink-0 border-2 border-white shadow-sm">
                            <Bot className="w-5 h-5 text-brand-600" />
                        </div>
                        <div className="bg-gray-100 rounded-2xl rounded-tl-none p-4 text-sm text-gray-800 shadow-sm max-w-[85%]">
                            我是您的AI助手。关于 {drug.brandNameCn || drug.brandName} 的使用、费用或针对您病情的适配性，您有什么想问的吗？
                        </div>
                    </div>

                    {chatHistory.map((msg, idx) => (
                        <div key={idx} className={`flex gap-3 ${msg.role === 'user' ? 'flex-row-reverse' : ''}`}>
                            <div className={`w-9 h-9 rounded-full flex items-center justify-center shrink-0 border-2 border-white shadow-sm ${msg.role === 'user' ? 'bg-gray-800' : 'bg-brand-100'}`}>
                                {msg.role === 'user' ? <User className="w-5 h-5 text-white" /> : <Bot className="w-5 h-5 text-brand-600" />}
                            </div>
                            <div className={`max-w-[85%] rounded-2xl p-4 text-sm shadow-sm ${
                                msg.role === 'user' 
                                ? 'bg-gray-900 text-white rounded-tr-none' 
                                : 'bg-gray-100 text-gray-800 rounded-tl-none'
                            }`}>
                                <ReactMarkdown>{msg.text}</ReactMarkdown>
                            </div>
                        </div>
                    ))}

                    {chatLoading && (
                        <div className="flex gap-3">
                             <div className="w-9 h-9 rounded-full bg-brand-100 flex items-center justify-center shrink-0 border-2 border-white shadow-sm">
                                <Bot className="w-5 h-5 text-brand-600" />
                            </div>
                            <div className="bg-gray-100 rounded-2xl rounded-tl-none p-4 text-sm text-gray-500 shadow-sm">
                                <span className="animate-pulse flex items-center gap-1">
                                    正在解答 <span className="animate-bounce">.</span><span className="animate-bounce delay-100">.</span><span className="animate-bounce delay-200">.</span>
                                </span>
                            </div>
                        </div>
                    )}
                </div>

                <div className="p-4 border-t border-gray-100 bg-white">
                    <div className="flex gap-3 relative">
                        <input
                            type="text"
                            value={input}
                            onChange={(e) => setInput(e.target.value)}
                            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                            placeholder="输入问题 (例如: 这个药在亚洲可以买到吗？)"
                            className="flex-1 border border-gray-200 bg-gray-50 rounded-xl px-5 py-3 pr-12 focus:ring-2 focus:ring-brand-500 focus:outline-none transition-shadow"
                        />
                        <button 
                            onClick={handleSend}
                            disabled={!input.trim() || chatLoading}
                            className="absolute right-2 top-2 p-1.5 bg-brand-600 text-white rounded-lg hover:bg-brand-700 disabled:opacity-50 transition-colors shadow-sm"
                        >
                            <Send className="w-5 h-5" />
                        </button>
                    </div>
                </div>
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Login } from './components/Login';
import { ProfileForm } from './components/ProfileForm';
import { ArticleCard } from './components/ArticleCard';
import { TrialCard } from './components/TrialCard';
import { DrugCard } from './components/DrugCard';
import { AIInterpreterModal } from './components/AIInterpreterModal';
import { DrugInterpreterModal } from './components/DrugInterpreterModal';
import { SavedInquiries } from './components/SavedInquiries';
import { Logo } from './components/Logo';
import { searchArticles } from './services/pubmedService';
import { fetchDmdTrials } from './services/trialService';
import { fetchDmdDrugs } from './services/fdaService';
import { logout, getCurrentUser, getUserData, saveUserProfile } from './services/authService';
import { UserProfile, Article, UserDatabaseEntry, ClinicalTrial, FDADrug } from './types';
import { Calendar, Loader2, Sparkles, LayoutGrid, Settings, Bookmark, Microscope, Pill } from 'lucide-react';

type ViewState = 'feed' | 'trials' | 'drugs' | 'settings' | 'saved';

const App: React.FC = () => {
  const [user, setUser] = useState<string | null>(null);
  const [userData, setUserData] = useState<UserDatabaseEntry | null>(null);
  const [currentView, setCurrentView] = useState<ViewState>('feed');

  const [articles, setArticles] = useState<Article[]>([]);
  const [trials, setTrials] = useState<ClinicalTrial[]>([]);
  const [drugs, setDrugs] = useState<FDADrug[]>([]);

  const [loading, setLoading] = useState(false);
  const [selectedArticle, setSelectedArticle] = useState<Article | null>(null);
  const [selectedDrug, setSelectedDrug] = useState<FDADrug | null>(null);
  const [timeRange, setTimeRange] = useState(1); 
  const [initializing, setInitializing] = useState(true);

  useEffect(() => {
    const currentUser = getCurrentUser();
    if (currentUser) {
      setUser(currentUser);
      const data = getUserData();
      setUserData(data);
      if (!data?.profile) setCurrentView('settings');
    }
    setInitializing(false);
  }, []);

  // Centralized Data Fetcher
  useEffect(() => {
    if (!user || !userData?.profile) return;

    const fetchData = async () => {
      setLoading(true);
      try {
        if (currentView === 'feed') {
          const data = await searchArticles(timeRange, userData.profile!.interests);
          setArticles(data);
        } else if (currentView === 'trials') {
          const data = await fetchDmdTrials();
          setTrials(data);
        } else if (currentView === 'drugs') {
          const data = await fetchDmdDrugs();
          setDrugs(data);
        }
      } catch (e) {
        console.error(e);
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, [user, userData, currentView, timeRange]);

  const handleLoginSuccess = () => {
    const u = getCurrentUser();
    setUser(u);
    const data = getUserData();
    setUserData(data);
    setCurrentView(data?.profile ? 'feed' : 'settings');
  };

  const handleLogout = async () => {
    await logout();
    setUser(null);
    setUserData(null);
    setArticles([]);
  };

  const handleProfileSave = async (profile: UserProfile) => {
      await saveUserProfile(profile);
      setUserData(getUserData());
      setCurrentView('feed');
  };

  if (initializing) {
      return <div className="min-h-screen flex items-center justify-center bg-slate-50"><Loader2 className="w-8 h-8 text-brand-500 animate-spin" /></div>;
  }

  if (!user) return <Login onLoginSuccess={handleLoginSuccess} />;

  if (!userData?.profile) {
      return (
          <div className="min-h-screen bg-brand-50 flex items-center justify-center p-4">
              <ProfileForm onSave={handleProfileSave} isInitialSetup={true} />
          </div>
      );
  }

  return (
    <div className="min-h-screen bg-slate-50 font-sans text-gray-900">

      {/* Navigation */}
      <header className="bg-white sticky top-0 z-30 border-b border-gray-200 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <Logo />

          <div className="flex items-center gap-2 md:gap-6">
             <nav className="flex items-center bg-gray-100 p-1 rounded-lg overflow-x-auto scrollbar-hide max-w-[200px] sm:max-w-none">
                 <button onClick={() => setCurrentView('feed')} className={`flex items-center px-3 py-1.5 rounded-md text-sm font-medium transition-all whitespace-nowrap ${currentView === 'feed' ? 'bg-white text-brand-700 shadow-sm' : 'text-gray-500'}`}>
                    <LayoutGrid className="w-4 h-4 mr-1 md:mr-2" />
                    资讯
                 </button>
                 <button onClick={() => setCurrentView('trials')} className={`flex items-center px-3 py-1.5 rounded-md text-sm font-medium transition-all whitespace-nowrap ${currentView === 'trials' ? 'bg-white text-brand-700 shadow-sm' : 'text-gray-500'}`}>
                    <Microscope className="w-4 h-4 mr-1 md:mr-2" />
                    试验
                 </button>
