export const chatWithContext = async (
    history: ChatMessage[], 
    newMessage: string, 
    context: string,
    profile: UserProfile,
    type: 'article' | 'trial' | 'drug'
): Promise<string> => {
    const ai = getClient();
    const systemInstruction = `
    你是一位DMD医学解读员。用户正在就一个特定的 ${type} 提问。

    ${type === 'trial' ? '当前讨论的临床试验：' : type === 'drug' ? '当前讨论的药物：' : '当前讨论的研究文章：'}
    ${context}

    患者背景: ${profile.ageGroup}, ${profile.ambulatoryStatus}, 基因: ${profile.geneticProfile}。

    核心规则：
    1. 你的回答必须**完全基于上述提供的 ${type} 信息**。
    2. 如果用户问“这个”或“该项目”，指的就是上述上下文中的内容。
    3. 严禁随意扩散到其他无关的药物或试验。
    4. 保持通俗易懂，始终包含免责声明："${DISCLAIMER}"。
    `;

    try {
        const chat = ai.chats.create({
            model: 'gemini-3-flash-preview',
            config: { systemInstruction },
            history: history.map(h => ({ role: h.role, parts: [{ text: h.text }] }))
        });
        const result = await chat.sendMessage({ message: newMessage });
        return result.text;
    } catch (error) {
        return "回复失败，请检查网络。";
    }
};

