  const [contractures, setContractures] = useState('');
  const [painWarnings, setPainWarnings] = useState('');
  const [duration, setDuration] = useState<10 | 20 | null>(null);

  // Workout state
  const [currentVideoIdx, setCurrentVideoIdx] = useState(0);
  const [timeLeft, setTimeLeft] = useState(0);
  const [isRunning, setIsRunning] = useState(false);
  const [nextDayTime, setNextDayTime] = useState('');

  const timerRef = useRef<NodeJS.Timeout | null>(null);
  const videoCount = duration === 10 ? 4 : 8;
  const currentVideos = REHAB_VIDEOS.slice(0, videoCount);

  useEffect(() => {
    if (isRunning && timeLeft > 0) {
      timerRef.current = setInterval(() => {
        setTimeLeft(prev => {
          if (prev <= 1) {
            handleVideoEnd();
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    } else {
      if (timerRef.current) clearInterval(timerRef.current);
    }
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [isRunning, timeLeft]);

  const handleVideoEnd = () => {
    if (currentVideoIdx < videoCount - 1) {
      setCurrentVideoIdx(prev => prev + 1);
      setTimeLeft(150); // Next 2.5 min video
    } else {
      setIsRunning(false);
      setStep('complete');
    }
  };

  const startWorkout = () => {
    setCurrentVideoIdx(0);
    setTimeLeft(150);
    setIsRunning(true);
    setStep('workout');
  };

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}:${s.toString().padStart(2, '0')}`;
  };

  return (
    <div className="max-w-4xl mx-auto animate-in fade-in slide-in-from-bottom-4 duration-500">

      {/* 1. Assessment Step */}
      {step === 'assessment' && (
        <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-8">
          <div className="flex items-center gap-4 mb-8">
            <div className="p-3 bg-brand-100 rounded-2xl">
              <Stethoscope className="w-8 h-8 text-brand-600" />
            </div>
            <div>
                <h1 className="text-2xl font-black text-gray-900 leading-tight">康复前评估</h1>
                <p className="text-gray-500 text-sm">Before unlocking routines, please let me know the trainee kid's details.</p>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
            <div className="bg-gray-50 p-4 rounded-xl border border-gray-100">
                <span className="text-xs font-bold text-gray-400 uppercase tracking-widest block mb-1">Age</span>
                <span className="text-lg font-bold text-gray-900">{profile.age} 岁</span>
            </div>
            <div className="bg-gray-50 p-4 rounded-xl border border-gray-100">
                <span className="text-xs font-bold text-gray-400 uppercase tracking-widest block mb-1">Ambulatory Status</span>
                <span className="text-lg font-bold text-gray-900">
                    {profile.ambulatoryStatus === 'ambulatory' ? '可独立行走' : profile.ambulatoryStatus === 'wheelchair' ? '需轮椅辅助' : '混合/辅助行走'}
                </span>
            </div>
          </div>

          <div className="space-y-6">
            <div>
              <label className="block text-sm font-bold text-gray-700 mb-2 flex items-center gap-2">
                <AlertCircle className="w-4 h-4 text-brand-500" />
                Any joint contractures? (关节挛缩情况)
              </label>
              <textarea 
                placeholder="例如：踝关节有轻微挛缩..."
                className="w-full border-gray-200 rounded-xl p-4 focus:ring-2 focus:ring-brand-500 outline-none transition-all h-24 bg-gray-50/50"
                value={contractures}
                onChange={e => setContractures(e.target.value)}
              />
            </div>
            <div>
              <label className="block text-sm font-bold text-gray-700 mb-2 flex items-center gap-2">
                <AlertCircle className="w-4 h-4 text-amber-500" />
                Any pain warnings? (疼痛预警)
              </label>
              <textarea 
                placeholder="例如：膝盖最近偶尔会疼..."
                className="w-full border-gray-200 rounded-xl p-4 focus:ring-2 focus:ring-brand-500 outline-none transition-all h-24 bg-gray-50/50"
                value={painWarnings}
                onChange={e => setPainWarnings(e.target.value)}
              />
            </div>
          </div>

          <button 
            disabled={!contractures || !painWarnings}
            onClick={() => setStep('setup')}
            className="w-full mt-8 bg-brand-600 text-white py-4 rounded-2xl font-bold hover:bg-brand-700 disabled:opacity-50 transition-all flex items-center justify-center gap-2 shadow-lg shadow-brand-500/20"
          >
            解锁每日康复计划
            <ChevronRight className="w-5 h-5" />
          </button>
        </div>
      )}

      {/* 2. Setup Step */}
      {step === 'setup' && (
        <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-8 text-center animate-in zoom-in-95 duration-300">
            <div className="w-20 h-20 bg-brand-100 rounded-full flex items-center justify-center mx-auto mb-6">
                <CheckCircle className="w-10 h-10 text-brand-600" />
            </div>
            <h2 className="text-2xl font-black text-gray-900 mb-4">谢谢，康复视频是根据孩子的情况定制...</h2>
            <p className="text-gray-500 mb-8 max-w-md mx-auto">我们已经根据您的反馈生成了适合的拉伸与活动度训练。请选择今天的康复时长：</p>

