                >
                    <span className="block text-2xl font-black text-gray-900">10 分钟</span>
                    <span className="text-sm text-gray-500">4 个针对性训练视频</span>
                </button>
                <button 
                    onClick={() => setDuration(20)}
                    className={`p-6 rounded-2xl border-2 transition-all ${duration === 20 ? 'border-brand-500 bg-brand-50' : 'border-gray-100 hover:border-brand-200'}`}
