                    <span className="block text-2xl font-black text-gray-900">20 分钟</span>
                    <span className="text-sm text-gray-500">8 个完整循环训练视频</span>
                </button>
            </div>

            <button 
                disabled={!duration}
                onClick={startWorkout}
                className="w-full mt-10 bg-brand-600 text-white py-4 rounded-2xl font-bold hover:bg-brand-700 disabled:opacity-50 transition-all flex items-center justify-center gap-2 shadow-xl shadow-brand-500/20"
            >
                <Play className="w-5 h-5 fill-current" />
                开始今日跟练
            </button>
        </div>
      )}

      {/* 3. Workout Step */}
      {step === 'workout' && (
        <div className="space-y-6">
            <div className="flex items-center justify-between px-2">
                <div className="flex items-center gap-3">
                    <div className="w-12 h-12 bg-white rounded-xl shadow-sm flex items-center justify-center border border-gray-100">
                        <Timer className="w-6 h-6 text-brand-600 animate-pulse" />
                    </div>
                    <div>
                        <h3 className="font-black text-gray-900">{currentVideos[currentVideoIdx].title}</h3>
