                    />
                    <button 
                        onClick={() => { alert(`已预约明天 ${nextDayTime} 的康复提醒！`); setStep('assessment'); }}
                        className="bg-brand-600 text-white px-6 py-3 rounded-xl font-bold hover:bg-brand-700 transition-all shadow-md"
                    >
                        确认预约
                    </button>
                </div>
            </div>

            <div className="mt-8">
                 <button onClick={() => setStep('assessment')} className="text-brand-600 font-bold hover:underline">返回康复中心</button>
            </div>
        </div>
      )}
    </div>
  );
};

